fn parse_backup(s: &str) -> Result<String, String> {
    let low = s.to_lowercase();
    if low == "none" || low == "off" || low == "numbered" || low == "auto" {
        Ok(low)
    } else {
        Err(format!("Invalid arguments: Unexpected value for 'backup': {}", s))
    }
}

fn build_command() -> Command {
    Command::new("xcp")
        .version("0.24.3")
        .about("A (partial) clone of the Unix `cp` command with progress and pluggable drivers.")
        .arg(Arg::new("PATHS").help("Path list").long_help("Path list.\n\nSource and destination files, or multiple source(s) to a directory.").num_args(0..))
        .arg(Arg::new("verbose").short('v').long("verbose").action(ArgAction::Count).help("Verbosity").long_help("Verbosity.\n\nCan be specified multiple times to increase logging."))
        .arg(Arg::new("recursive").short('r').long("recursive").action(ArgAction::SetTrue).help("Copy directories recursively"))
        .arg(Arg::new("dereference").short('L').long("dereference").action(ArgAction::SetTrue).help("Dereference symlinks in source").long_help("Dereference symlinks in source\n\nFollow symlinks, possibly recursively, when copying source files."))
        .arg(Arg::new("workers").short('w').long("workers").value_name("WORKERS").default_value("4").value_parser(clap::value_parser!(u64)).help("Number of parallel workers").long_help("Number of parallel workers.\n\nDefault is 4; if the value is negative or 0 it uses the number of logical CPUs."))
        .arg(Arg::new("block-size").long("block-size").value_name("BLOCK_SIZE").default_value("1MB").value_parser(parse_block_size).help("Block size for operations").long_help("Block size for operations.\n\nAccepts standard size modifiers like \"M\" and \"GB\". Actual usage internally depends on the driver."))
        .arg(Arg::new("no-clobber").short('n').long("no-clobber").action(ArgAction::SetTrue).help("Do not overwrite an existing file"))
        .arg(Arg::new("force").short('f').long("force").action(ArgAction::SetTrue).help("Force (compatability only)").long_help("Force (compatability only)\n\nOverwrite files; this is the default behaviour, this flag is for compatibility with `cp` only. See `--no-clobber` for the inverse flag. Using this in conjunction with `--no-clobber` will cause an error."))
        .arg(Arg::new("gitignore").long("gitignore").action(ArgAction::SetTrue).help("Use .gitignore if present").long_help("Use .gitignore if present.\n\nNOTE: This is fairly basic at the moment, and only honours a .gitignore in the directory root for directory copies; global or sub-directory ignores are skipped."))
        .arg(Arg::new("glob").short('g').long("glob").action(ArgAction::SetTrue).help("Expand file patterns").long_help("Expand file patterns.\n\nGlob (expand) filename patterns natively (note; the shell may still do its own expansion first)"))
        .arg(Arg::new("no-progress").long("no-progress").action(ArgAction::SetTrue).help("Disable progress bar"))
        .arg(Arg::new("no-perms").long("no-perms").action(ArgAction::SetTrue).help("Do not copy the file permissions"))
        .arg(Arg::new("no-timestamps").long("no-timestamps").action(ArgAction::SetTrue).help("Do not copy the file timestamps"))
        .arg(Arg::new("ownership").short('o').long("ownership").action(ArgAction::SetTrue).help("Copy ownership").long_help("Copy ownership.\n\nWhether to copy ownship (user/group).  This option requires root permissions or appropriate capabilities; if the attempt to copy ownership fails a warning is issued but the operation continues."))
        .arg(Arg::new("driver").long("driver").value_name("DRIVER").default_value("parfile").value_parser(parse_driver).help("Driver to use, defaults to 'file-parallel'").long_help("Driver to use, defaults to 'file-parallel'.\n\nCurrently there are 2; the default \"parfile\", which parallelises copies across workers at the file level, and an experimental \"parblock\" driver, which parellelises at the block level. See also '--block-size'." ))
        .arg(Arg::new("no-target-directory").short('T').long("no-target-directory").action(ArgAction::SetTrue).help("Target should not be a directory").long_help("Target should not be a directory.\n\nAnalogous to cp's no-target-directory. Expected behavior is that when copying a directory to another directory, instead of creating a sub-folder in target, overwrite target."))
        .arg(Arg::new("target-directory").long("target-directory").value_name("TARGET_DIRECTORY").help("Copy into a subdirectory of the target"))
        .arg(Arg::new("fsync").long("fsync").action(ArgAction::SetTrue).help("Sync each file to disk after writing"))
        .arg(Arg::new("reflink").long("reflink").value_name("REFLINK").default_value("auto").value_parser(parse_reflink).help("Reflink options").long_help("Reflink options.\n\nWhether and how to use reflinks. 'auto' (the default) will attempt to reflink and fallback to a copy if it is not possible, 'always' will return an error if it cannot reflink, and 'never' will always perform a full data copy.\n\nNote: when using Linux accelerated copy operations (the default when available) the kernel may choose to reflink rather than perform a fully copy regardless of this setting."))
        .arg(Arg::new("backup").long("backup").value_name("BACKUP").default_value("none").value_parser(parse_backup).help("Backup options").long_help("Backup options\n\nWhether to create backups of overwritten files. Current options are 'none'/'off', or 'numbered', or 'auto'. Numbered backups follow the semantics of `cp` numbered backups (e.g. `file.txt.~123~`). 'auto' will only create a numbered backup if a previous backups exists. Default is 'none'."))
}

fn main() {
    let cmd = build_command();
    let matches = cmd.try_get_matches_from(std::env::args());
    let m = match matches {
        Ok(m) => m,
        Err(e) => e.exit(),
    };
    std::process::exit(run(m));
}

fn run(m: clap::ArgMatches) -> i32 {
    // force + noclobber check
    if m.get_flag("force") && m.get_flag("no-clobber") {
        eprintln!("Error: Invalid arguments: --force and --noclobber cannot be set at the same time.");
        return 1;
    }
    // reflink never warning (always to stdout, even without verbose)
    if let Some(r) = m.get_one::<String>("reflink") {
        if r.to_lowercase() == "never" {
            println!("{} [WARN] --reflink=never is selected, however the Linux kernel may override this.", timestamp());
        }
    }
    // ... rest will be implemented
    eprintln!("Error: Invalid arguments: Insufficient arguments");
    1
}
