fn copy_xattrs(src: &Path, dst: &Path, is_symlink_dst: bool) {
    // Best effort, ignore errors
    // Use llistxattr etc. via libc
    use std::ffi::CString;
    use std::os::unix::ffi::OsStrExt;
    // Get list size
    unsafe {
        let src_c = match CString::new(src.as_os_str().as_bytes()) {
            Ok(c) => c,
            Err(_) => return,
        };
        let dst_c = match CString::new(dst.as_os_str().as_bytes()) {
            Ok(c) => c,
            Err(_) => return,
        };
        // llistxattr
        let sz = libc::llistxattr(src_c.as_ptr(), std::ptr::null_mut(), 0);
        if sz <= 0 {
            return;
        }
        let mut buf = vec![0u8; sz as usize];
        let sz2 = libc::llistxattr(src_c.as_ptr(), buf.as_mut_ptr() as *mut i8, sz as usize);
        if sz2 <= 0 {
            return;
        }
        // buf contains null-separated names
        let mut i = 0;
        while i < sz2 as usize {
            let mut j = i;
            while j < sz2 as usize && buf[j] != 0 {
                j += 1;
            }
            if j > i {
                let name_bytes = &buf[i..j];
                // get value size
                let name_c = match CString::new(name_bytes) {
                    Ok(c) => c,
                    Err(_) => { i = j+1; continue; }
                };
                let vsz = libc::lgetxattr(src_c.as_ptr(), name_c.as_ptr(), std::ptr::null_mut(), 0);
                if vsz < 0 {
                    i = j+1;
                    continue;
                }
                let mut vbuf = vec![0u8; vsz as usize];
                let vsz2 = libc::lgetxattr(src_c.as_ptr(), name_c.as_ptr(), vbuf.as_mut_ptr() as *mut std::ffi::c_void, vsz as usize);
                if vsz2 < 0 {
                    i = j+1;
                    continue;
                }
                // set on dst (use lsetxattr)
                let _ = libc::lsetxattr(dst_c.as_ptr(), name_c.as_ptr(), vbuf.as_ptr() as *const std::ffi::c_void, vsz2 as usize, 0);
            }
            i = j+1;
        }
        let _ = is_symlink_dst;
    }
}

fn copy_perms(src: &Path, dst: &Path, no_perms: bool) {
    if no_perms {
        return;
    }
    if let Ok(md) = std::fs::symlink_metadata(src) {
        // For symlinks, chmod is no-op (and would follow). Skip for symlinks.
        if md.file_type().is_symlink() {
            return;
        }
        let mode = std::os::unix::fs::PermissionsExt::mode(&md.permissions());
        let perm = std::fs::Permissions::from_mode(mode);
        let _ = std::fs::set_permissions(dst, perm);
    }
}
fn copy_timestamps(src: &Path, dst: &Path, no_timestamps: bool) {
    if no_timestamps {
        return;
    }
    // Skip for symlinks? Use lutimens? For now, skip symlinks.
    if let Ok(md) = std::fs::symlink_metadata(src) {
        if md.file_type().is_symlink() {
            return;
        }
    }
    unsafe {
        use std::os::unix::ffi::OsStrExt;
        use std::ffi::CString;
        let src_c = match CString::new(src.as_os_str().as_bytes()) {
            Ok(c) => c,
            Err(_) => return,
        };
        let dst_c = match CString::new(dst.as_os_str().as_bytes()) {
            Ok(c) => c,
            Err(_) => return,
        };
        let mut st: libc::stat = std::mem::zeroed();
        if libc::stat(src_c.as_ptr(), &mut st) != 0 {
            return;
        }
        let times = [
