fn parse_block_size(s: &str) -> Result<u64, String> {
    if s.trim().is_empty() {
        panic_block_size();
    }
    let trimmed = s.trim();
    let nospace: String = trimmed.chars().filter(|c| !c.is_whitespace()).collect();
    if nospace.is_empty() {
        panic_block_size();
    }
    let low_nospace = nospace.to_lowercase();
    if low_nospace == "inf" || low_nospace == "+inf" || low_nospace == "-inf"
        || low_nospace == "infinity" || low_nospace == "+infinity" || low_nospace == "-infinity"
        || low_nospace == "nan" || low_nospace == "+nan" || low_nospace == "-nan" {
        return Ok(u64::MAX);
    }
    let suffixes = ["kib","mib","gib","tib","pib","eib","zib","yib","kb","mb","gb","tb","pb","eb","zb","yb","k","m","g","t","p","e","z","y","b",""];
    let mut num_part = nospace.as_str();
    let mut suffix_part = "";
    let lower = nospace.to_lowercase();
    for suf in suffixes.iter() {
        if suf.is_empty() { continue; }
        if lower.ends_with(suf) {
            let idx = nospace.len() - suf.len();
            num_part = &nospace[..idx];
            suffix_part = &nospace[idx..];
            break;
        }
    }
    if num_part.is_empty() && !suffix_part.is_empty() {
        return Err("could not interpret string as byte size".to_string());
    }
    if suffix_part.is_empty() {
        num_part = nospace.as_str();
    }
    let num: f64 = match num_part.parse() {
        Ok(v) => v,
        Err(_) => return Err("could not interpret string as byte size".to_string()),
    };
    if !num.is_finite() {
        return Ok(u64::MAX);
    }
    if num < 0.0 {
        return Err("could not interpret string as byte size".to_string());
    }
    let mult: f64 = match suffix_part.to_lowercase().as_str() {
        "" | "b" => 1.0,
        "k" | "kb" | "kib" => 1000.0,
        "m" | "mb" | "mib" => 1000.0*1000.0,
        "g" | "gb" | "gib" => 1000.0*1000.0*1000.0,
        "t" | "tb" | "tib" => 1000.0*1000.0*1000.0*1000.0,
        "p" | "pb" | "pib" => 1000.0*1000.0*1000.0*1000.0*1000.0,
        "e" | "eb" | "eib" => 1000.0*1000.0*1000.0*1000.0*1000.0*1000.0,
        "z" | "zb" | "zib" => 1000.0*1000.0*1000.0*1000.0*1000.0*1000.0*1000.0,
        "y" | "yb" | "yib" => 1000.0*1000.0*1000.0*1000.0*1000.0*1000.0*1000.0*1000.0,
        _ => return Err("could not interpret string as byte size".to_string()),
    };
    let bytes = num * mult;
    if bytes.fract() != 0.0 {
        let rounded = bytes.round();
        if (bytes - rounded).abs() > 1e-6 {
            return Err("could not interpret string as byte size".to_string());
        }
    }
    if bytes > (u64::MAX as f64) {
        return Err("could not interpret string as byte size".to_string());
    }
    Ok(bytes as u64)
}

