fn handle_backup(dst: &Path, backup: &str, verbose: u8) -> Result<(), String> {
    if backup == "none" || backup == "off" {
        return Ok(());
    }
    if !dst.exists() && !dst.symlink_metadata().is_ok() {
        // No existing file, no backup needed (even for numbered? Original with numbered and no existing file just copies, no backup file. Good.)
        return Ok(());
    }
    if backup == "numbered" {
        // Find next available ~N~
        let mut n = 1;
        loop {
            let backup_path = format!("{}.~{}~", dst.to_string_lossy(), n);
            if !Path::new(&backup_path).exists() {
                // Rename dst to backup
                if verbose >= 1 {
                    println!("{} [INFO] Backup: Rename {:?} to {:?}", timestamp(), dst.to_string_lossy().to_string(), backup_path);
                }
                if let Err(e) = std::fs::rename(dst, &backup_path) {
                    return Err(format!("Error during copy: {}", os_error_str(&e)));
                }
                break;
            }
            n += 1;
            if n > 100000 {
                return Err("Error during copy: Too many backups".to_string());
            }
        }
        Ok(())
    } else if backup == "auto" {
        // Only if previous backup exists: check if any ~N~ exists?
        let dst_str = dst.to_string_lossy().to_string();
        // Check for existing backup files: look for dst.~*~ ?
        // List parent dir?
        if let Some(parent) = dst.parent() {
            if let Ok(entries) = std::fs::read_dir(parent) {
                let mut has_backup = false;
                let base = dst.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
                for e in entries.flatten() {
                    let name = e.file_name().to_string_lossy().to_string();
                    // Check if name matches base.~N~
                    if name.starts_with(&format!("{}.~", base)) && name.ends_with('~') {
                        // Check middle is number?
                        let mid = &name[base.len()+2..name.len()-1];
                        if !mid.is_empty() && mid.chars().all(|c| c.is_ascii_digit()) {
                            has_backup = true;
                            break;
                        }
                    }
                }
                if !has_backup {
                    return Ok(());
                }
            }
        } else {
            return Ok(());
        }
        // Has backup, do numbered
        let mut n = 1;
        loop {
            let backup_path = format!("{}.~{}~", dst_str, n);
            if !Path::new(&backup_path).exists() {
                if verbose >= 1 {
                    println!("{} [INFO] Backup: Rename {:?} to {:?}", timestamp(), dst_str, backup_path);
                }
                if let Err(e) = std::fs::rename(dst, &backup_path) {
                    return Err(format!("Error during copy: {}", os_error_str(&e)));
                }
                break;
            }
            n += 1;
            if n > 100000 {
                return Err("Error during copy: Too many backups".to_string());
            }
        }
        Ok(())
    } else {
        Ok(())
    }
}

fn copy_regular_file(src: &Path, dst: &Path, cfg: &Config) -> Result<(), String> {
    // Check same inode? If same dev+ino, return EINVAL (like original)
    unsafe {
        use std::os::unix::ffi::OsStrExt;
        use std::ffi::CString;
        let src_c = CString::new(src.as_os_str().as_bytes()).unwrap();
        let dst_c = CString::new(dst.as_os_str().as_bytes()).unwrap();
        let mut st_src: libc::stat = std::mem::zeroed();
        let mut st_dst: libc::stat = std::mem::zeroed();
        let src_stat_ok = libc::stat(src_c.as_ptr(), &mut st_src) == 0;
        let dst_stat_ok = libc::stat(dst_c.as_ptr(), &mut st_dst) == 0;
        if src_stat_ok && dst_stat_ok && st_src.st_dev == st_dst.st_dev && st_src.st_ino == st_dst.st_ino {
            return Err("Error during copy: Invalid argument (os error 22)".to_string());
        }
    }
    // Open src
    let mut src_file = std::fs::File::open(src).map_err(|e| format!("Error during copy: {}", os_error_str(&e)))?;
    // Create parent for dst? For file copies, do NOT create parents (fail if parent missing). So just try to create dst.
    // Handle backup/noclobber already done outside? Actually backup/noclobber for files is handled here or outside? We'll handle outside before calling.
    // Create dst file (truncate)
    let dst_file = std::fs::File::create(dst).map_err(|e| format!("Error during copy: {}", os_error_str(&e)))?;
    // Sparse-aware copy: read chunks, if all zeros, seek instead of write
    use std::io::{Read, Write, Seek, SeekFrom};
    let mut src_f = src_file;
    let mut dst_f = dst_file;
    let mut buf = vec![0u8; 64*1024];
    loop {
        let n = src_f.read(&mut buf).map_err(|e| format!("Error during copy: {}", os_error_str(&e)))?;
        if n == 0 { break; }
        let chunk = &buf[..n];
        let is_zero = chunk.iter().all(|&b| b == 0);
        if is_zero {
            // Seek in dst instead of writing
            dst_f.seek(SeekFrom::Current(n as i64)).map_err(|e| format!("Error during copy: {}", os_error_str(&e)))?;
        } else {
            dst_f.write_all(chunk).map_err(|e| format!("Error during copy: {}", os_error_str(&e)))?;
        }
    }
    // Truncate dst to src len? For sparse with trailing zeros, seeking beyond may leave size larger? Actually seeking past and then closing will leave file with holes but size correct? Need to ensure size matches src.
    // Get src len
    if let Ok(md) = std::fs::metadata(src) {
        let len = md.len();
        dst_f.set_len(len).map_err(|e| format!("Error during copy: {}", os_error_str(&e)))?;
    }
    if cfg.fsync {
        let _ = dst_f.sync_all();
    }
    drop(dst_f);
    // Copy xattrs, perms, timestamps, ownership
    copy_xattrs(src, dst, false);
    copy_perms(src, dst, cfg.no_perms);
    copy_timestamps(src, dst, cfg.no_timestamps);
    // For ownership, need is_symlink false
    copy_ownership(src, dst, cfg.ownership, false);
    Ok(())
}

