                        }
                        if dst_entry.symlink_metadata().is_ok() {
                            let _ = std::fs::remove_file(&dst_entry);
                            let _ = std::fs::remove_dir(&dst_entry);
                        }
                        match copy_special(&src_entry, &dst_entry, cfg) {
                            Ok(_) => continue,
                            Err(raw) => {
                                if raw.starts_with("Error") {
                                    eprintln!("{}", raw);
                                } else {
                                    eprintln!("Error: {}", raw);
                                }
                                return Err(1);
                            }
                        }
                    }
                }
                // Regular file (or dereferenced symlink to file, but here src_entry is not symlink without deref, so either regular or symlink with deref)
                let (src_log, src_copy) = if std::fs::symlink_metadata(&src_entry).map(|m| m.file_type().is_symlink()).unwrap_or(false) && cfg.dereference {
                    if let Ok(c) = std::fs::canonicalize(&src_entry) {
                        (c.to_string_lossy().to_string(), c)
                    } else {
                        (src_entry.to_string_lossy().to_string(), src_entry.clone())
                    }
                } else {
                    (src_entry.to_string_lossy().to_string(), src_entry.clone())
                };
                let dst_exists = dst_entry.symlink_metadata().is_ok();
                if cfg.no_clobber && dst_exists {
                    log_error(&format!("Received error: Destination Exists: Destination file exists and --no-clobber is set., {}", dst_entry.to_string_lossy()));
                    eprintln!("Error: Destination Exists: Destination file exists and --no-clobber is set., {}", dst_entry.to_string_lossy());
                    return Err(1);
                }
                if dst_exists {
                    if let Err(msg) = handle_backup(&dst_entry, &cfg.backup, cfg.verbose) {
                        log_error(&format!("Received error: {}", msg));
                        eprintln!("Error: {}", msg);
                        return Err(1);
                    }
                }
                if cfg.driver == "parblock" {
                    log_info(cfg.verbose, &format!("Dispatch[{:?}]: Copy {:?} -> {:?}", std::thread::current().id(), src_log, dst_entry.to_string_lossy().to_string()));
                } else {
                    log_info(cfg.verbose, &format!("Worker[{:?}]: Copy {:?} -> {:?}", std::thread::current().id(), src_log, dst_entry.to_string_lossy().to_string()));
                }
                // Check same inode? copy_regular_file will handle
                if dst_entry.symlink_metadata().map(|m| m.file_type().is_symlink()).unwrap_or(false) {
                    let _ = std::fs::remove_file(&dst_entry);
                }
                match copy_regular_file(&src_copy, &dst_entry, cfg) {
                    Ok(_) => {},
                    Err(msg) => {
                        log_error(&format!("Error copying: {:?} -> {:?}; aborting.", src_entry.to_string_lossy().to_string(), dst_entry.to_string_lossy().to_string()));
                        log_error(&format!("Received error: {}", msg));
                        eprintln!("Error: {}", msg);
                        return Err(1);
                    }
                }
            }
        }
    }
    Ok(())
}
RS
"}

