fn copy_dir_recursive(src_root: &Path, dst_root: &Path, git_pats: &[String], cfg: &Config) -> Result<(), i32> {
    // Walk src_root recursively, copy each entry to dst_root
    let mut stack = vec![PathBuf::from(src_root)];
    // To avoid infinite recursion when dst is inside src (bug case), check if dst is inside src and skip? For now, detect and return error early? Actually run already handles same-file, but not dst-inside-src. We'll handle here: if dst_root starts with src_root, then walking will include dst (which is being created). To avoid infinite, skip dst path.
